import base64 as _base64
import types as _types

def _load_module(name: str, source_b64: str):
    """Decode base64-encoded source and execute it in a fresh module.

    Each model file is loaded into its OWN namespace so helper classes
    that happen to share names across files (CDC_T, ConvBlock3D, ...)
    do not collide.
    """
    source = _base64.b64decode(source_b64.encode('ascii')).decode('utf-8')
    mod = _types.ModuleType(name)
    exec(compile(source, f'<inlined:{name}>', 'exec'), mod.__dict__)
    return mod

_M_DEEPPHYS = _load_module('_M_DEEPPHYS', _SRC_DEEPPHYS)
_M_TSCAN = _load_module('_M_TSCAN', _SRC_TSCAN)
_M_EFFICIENTPHYS = _load_module('_M_EFFICIENTPHYS', _SRC_EFFICIENTPHYS)
_M_PHYSNET = _load_module('_M_PHYSNET', _SRC_PHYSNET)
_M_PHYSFORMER = _load_module('_M_PHYSFORMER', _SRC_PHYSFORMER)
_M_PHYSMAMBA = _load_module('_M_PHYSMAMBA', _SRC_PHYSMAMBA)
_M_RHYTHMFORMER = _load_module('_M_RHYTHMFORMER', _SRC_RHYTHMFORMER)
_M_BIGSMALL = _load_module('_M_BIGSMALL', _SRC_BIGSMALL)
_M_IBVPNET = _load_module('_M_IBVPNET', _SRC_IBVPNET)
_M_FACTORIZEPHYS = _load_module('_M_FACTORIZEPHYS', _SRC_FACTORIZEPHYS)

# ============================================================================
# End of inlined model source code.
# ============================================================================

class BigSmallONNXWrapper(torch.nn.Module):
    def __init__(self, model):
        super(BigSmallONNXWrapper, self).__init__()
        self.model = model

    def forward(self, big_input, small_input):
        return self.model((big_input, small_input))

class PhysFormerONNXWrapper(torch.nn.Module):
    def __init__(self, model, gra_sharp: float = 1.0):
        super(PhysFormerONNXWrapper, self).__init__()
        self.model = model
        self.gra_sharp = gra_sharp

    def forward(self, video_clip):
        # Call .forward() directly to pass gra_sharp as a Python constant;
        # using self.model(...) would lose the float arg during ONNX tracing.
        output = self.model.forward(video_clip, self.gra_sharp)
        if isinstance(output, tuple):
            return output[0]
        return output

# ---------------------------------------------------------------------------
# Model factory
# ---------------------------------------------------------------------------

def build_model(model_name: str, args):
    """Instantiate the requested model in eval mode."""
    name = model_name.lower()

    if name == "deepphys":

        model = _M_DEEPPHYS.DeepPhys(img_size=args.img_size)
        # Input: (N, 6, H, W)  — DiffNorm (3ch) + Standardized (3ch)
        dummy = torch.zeros(1, 6, args.img_size, args.img_size)
        input_names = ["appearance_motion_input"]
        dynamic = {"appearance_motion_input": {0: "batch"}, "output": {0: "batch"}}

    elif name == "tscan":

        model = _M_TSCAN.TSCAN(frame_depth=args.frame_depth, img_size=args.img_size)
        dummy = torch.zeros(args.frame_depth, 6, args.img_size, args.img_size)
        input_names = ["frame_sequence"]
        dynamic = {"frame_sequence": {0: "T"}, "output": {0: "T"}}

    elif name == "physnet":

        model = _M_PHYSNET.PhysNet_padding_Encoder_Decoder_MAX(frames=args.chunk)
        dummy = torch.zeros(1, 3, args.chunk, args.img_size, args.img_size)
        input_names = ["video_clip"]
        dynamic = {"video_clip": {0: "batch"}, "output": {0: "batch"}}

    elif name == "efficientphys":

        model = _M_EFFICIENTPHYS.EfficientPhys(frame_depth=args.frame_depth, img_size=args.img_size)
        dummy = torch.zeros(args.frame_depth + 1, 3, args.img_size, args.img_size)
        input_names = ["frame_sequence"]
        dynamic = {"frame_sequence": {0: "T"}, "output": {0: "T"}}

    elif name == "physformer":

        # PhysFormer requires img_size=128 (so stem+patch output is 4×4 spatial)
        # and chunk=160 (standard training length); override any CLI values.
        pf_chunk = 160
        pf_img   = 128
        model = _M_PHYSFORMER.ViT_ST_ST_Compact3_TDC_gra_sharp(
            image_size=(pf_chunk, pf_img, pf_img),
            patches=(4, 4, 4), dim=96, ff_dim=144, num_heads=4,
            num_layers=12, dropout_rate=0.2, theta=0.7,
        )
        model = PhysFormerONNXWrapper(model, gra_sharp=1.0)
        dummy = torch.zeros(1, 3, pf_chunk, pf_img, pf_img)
        input_names = ["video_clip"]
        dynamic = {"video_clip": {0: "batch"}, "output": {0: "batch"}}

    elif name == "physmamba":

        model = _M_PHYSMAMBA.PhysMamba(frames=args.chunk)
        dummy = torch.zeros(1, 3, args.chunk, args.img_size, args.img_size)
        input_names = ["video_clip"]
        dynamic = {"video_clip": {0: "batch"}, "output": {0: "batch"}}

    elif name == "rhythmformer":

        model = _M_RHYTHMFORMER.RhythmFormer()
        dummy = torch.zeros(1, args.chunk, 3, args.img_size, args.img_size)
        input_names = ["video_clip"]
        dynamic = {"video_clip": {0: "batch"}, "output": {0: "batch"}}

    elif name == "bigsmall":

        model = _M_BIGSMALL.BigSmall(n_segment=args.chunk)
        model = BigSmallONNXWrapper(model)
        dummy_big   = torch.zeros(args.chunk, 3, 144, 144)
        dummy_small = torch.zeros(args.chunk, 3,   9,   9)
        dummy = (dummy_big, dummy_small)
        input_names = ["big_frames", "small_frames"]
        dynamic = {
            "big_frames":   {0: "T"},
            "small_frames": {0: "T"},
            "output":       {0: "T"},
        }

    elif name == "ibvpnet":

        model = _M_IBVPNET.iBVPNet(frames=args.chunk, in_channels=3)
        dummy = torch.zeros(1, 3, args.chunk + 1, args.img_size, args.img_size)
        input_names = ["video_clip"]
        dynamic = {"video_clip": {0: "batch"}, "output": {0: "batch"}}

    elif name == "factorizephys":

        md_config = {
            "FRAME_NUM": args.chunk, "MD_FSAM": True, "MD_TYPE": "NMF",
            "MD_R": 1, "MD_S": 1, "MD_STEPS": 3,
            "MD_RESIDUAL": True, "MD_INFERENCE": True, "MD_TRANSFORM": "T_KAB",
        }
        model = _M_FACTORIZEPHYS.FactorizePhys(frames=args.chunk, md_config=md_config, in_channels=3)
        dummy = torch.zeros(1, 3, args.chunk + 1, args.img_size, args.img_size)
        input_names = ["video_clip"]
        dynamic = {"video_clip": {0: "batch"}, "output": {0: "batch"}}

    else:
        raise ValueError(f"Unknown model: {model_name}")

    return model, dummy, input_names, dynamic

# ---------------------------------------------------------------------------
# Export
# ---------------------------------------------------------------------------

def export(args):
    print(f"[export] Model   : {args.model}")
    print(f"[export] Weights : {args.weights}")
    print(f"[export] Output  : {args.output}")

    model, dummy, input_names, dynamic_axes = build_model(args.model, args)

    state_dict = torch.load(args.weights, map_location="cpu")
    if any(k.startswith("module.") for k in state_dict):
        state_dict = {k[len("module."):]: v for k, v in state_dict.items()}
    model.load_state_dict(state_dict, strict=False)
    model.eval()

    os.makedirs(os.path.dirname(os.path.abspath(args.output)), exist_ok=True)

    with torch.no_grad():
        torch.onnx.export(
            model,
            dummy,
            args.output,
            opset_version=18,
            input_names=input_names,
            output_names=["output"],
            dynamic_axes=dynamic_axes,
            do_constant_folding=True,
        )

    print(f"[export] ONNX saved → {args.output}")

    # Save model metadata alongside the ONNX file
    meta = {
        "model":      args.model,
        "weights":    args.weights,
        "img_size":   args.img_size,
        "chunk":      args.chunk,
        "frame_depth": args.frame_depth,
        "opset":      18,
    }
    meta_path = args.output.replace(".onnx", "_meta.json")
    with open(meta_path, "w") as f:
        json.dump(meta, f, indent=2)
    print(f"[export] Metadata → {meta_path}")

    # Validate: compare PyTorch vs ONNX output
    if args.validate:
        _validate(model, dummy, args.output)

def _validate(model, dummy, onnx_path: str, tol: float = 1e-4):
    try:
        import onnxruntime as ort
        import numpy as np
    except ImportError:
        print("[validate] onnxruntime not installed — skipping validation")
        return

    if isinstance(dummy, tuple):
        pt_inputs = [x.unsqueeze(0) if x.dim() == 3 else x for x in dummy]
    else:
        pt_inputs = [dummy]

    with torch.no_grad():
        pt_out = model(*pt_inputs) if len(pt_inputs) > 1 else model(pt_inputs[0])

    if isinstance(pt_out, tuple):
        pt_out = pt_out[0]
    pt_np = pt_out.cpu().numpy()

    sess = ort.InferenceSession(onnx_path, providers=["CPUExecutionProvider"])
    ort_inputs = {
        sess.get_inputs()[i].name: (pt_inputs[i].numpy() if len(pt_inputs) > 1 else pt_inputs[0].numpy())
        for i in range(len(sess.get_inputs()))
    }
    ort_out = sess.run(None, ort_inputs)[0]

    max_diff = np.abs(pt_np - ort_out).max()
    status = "PASS" if max_diff < tol else "FAIL"
    print(f"[validate] Max diff PyTorch vs ONNX: {max_diff:.2e}  [{status}]")

# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def get_args():
    p = argparse.ArgumentParser(description="Export rPPG model to ONNX")
    p.add_argument("--model",      required=True, help="Model name (e.g. DeepPhys)")
    p.add_argument("--weights",    required=True, help="Path to .pth weights file")
    p.add_argument("--output",     required=True, help="Output .onnx path")
    p.add_argument("--img-size",   type=int, default=72,  dest="img_size")
    p.add_argument("--chunk",      type=int, default=180, help="Temporal chunk length")
    p.add_argument("--frame-depth",type=int, default=10,  dest="frame_depth")
    p.add_argument("--validate",   action="store_true",   help="Validate ONNX vs PyTorch")
    return p.parse_args()

if __name__ == "__main__":
    export(get_args())
